  const siteHeader = document.querySelector(".site-header");
  if (siteHeader) {
    const isToolPage = window.location.pathname.includes("/ferramentas/");
    const toolPath = isToolPage ? "../ferramentas/" : "ferramentas/";
    const currentPath = window.location.pathname;
    const indexNavigation = document.createElement("nav");
    indexNavigation.className = "tool-index";
    indexNavigation.setAttribute("aria-label", "Tool index");

    const indexInner = document.createElement("div");
    indexInner.className = "tool-index-inner";

    const indexLabel = document.createElement("span");
    indexLabel.className = "tool-index-label";
    indexLabel.textContent = "Tools";
    indexInner.append(indexLabel);

    const indexList = document.createElement("ul");
    indexList.className = "tool-index-list";

    toolIndex.forEach(([label, file]) => {
      const item = document.createElement("li");
      const link = document.createElement("a");
      link.href = `${toolPath}${file}`;
      link.textContent = label;
      if (currentPath.endsWith(`/ferramentas/${file}`)) {
        link.setAttribute("aria-current", "page");
      }
      item.append(link);
      indexList.append(item);
    });

    indexInner.append(indexList);
    indexNavigation.append(indexInner);
    siteHeader.insertAdjacentElement("afterend", indexNavigation);
  }

  const isToolPage = window.location.pathname.includes("/ferramentas/");
  const sitePath = isToolPage ? "../" : "";
  const footerNav = document.querySelector(".footer-nav");
  if (footerNav) {
    [
      ["About", "sobre.html"],
      ["Contact", "contato.html"],
      ["Cookie notice", "cookies.html"]
    ].forEach(([label, file]) => {
      const href = `${sitePath}${file}`;
      if (!footerNav.querySelector(`a[href="${href}"]`)) {
        const link = document.createElement("a");
        link.href = href;
        link.textContent = label;
        footerNav.append(link);
      }
    });
  }

  const cookieNoticeDismissed = localStorage.getItem("cookie-notice-dismissed") === "true";
  if (!cookieNoticeDismissed && document.body) {
    const cookieNotice = document.createElement("aside");
    cookieNotice.className = "cookie-notice";
    cookieNotice.setAttribute("role", "region");
    cookieNotice.setAttribute("aria-label", "Cookie and storage notice");

    const noticeCopy = document.createElement("div");
    noticeCopy.className = "cookie-notice-copy";

    const noticeTitle = document.createElement("h2");
    noticeTitle.textContent = "Cookie and storage notice";

    const noticeText = document.createElement("p");
    noticeText.textContent = "This site currently does not run advertising or analytics scripts. It stores your language preference and notice dismissal in browser local storage. Some tools load code from jsDelivr, cdnjs, or SheetJS CDN; those services receive standard connection data when requested. Closing this notice is not consent to advertising or tracking.";

    const noticeLink = document.createElement("a");
    noticeLink.href = `${sitePath}cookies.html`;
    noticeLink.textContent = "Read the full cookie notice";

    const dismissButton = document.createElement("button");
    dismissButton.className = "button button-secondary";
    dismissButton.type = "button";
    dismissButton.textContent = "Dismiss notice";
    dismissButton.addEventListener("click", () => {
      localStorage.setItem("cookie-notice-dismissed", "true");
      cookieNotice.remove();
    });

    noticeCopy.append(noticeTitle, noticeText, noticeLink);
    cookieNotice.append(noticeCopy, dismissButton);
    document.body.append(cookieNotice);
  }

